static void Main(string[] args)
{
    int num = 0;
    int D = 0, H, M, S;
    for (int i = 1; i <= 3; i++)
    {
        Console.WriteLine("Enter a six-digit integer : ");
        num = int.Parse(Console.ReadLine());
        S = num % 100;
        M = num / 100 % 100;
        H = num / 10000;
        if (S > 60)
        {
            M += S / 60;
            S = S % 60;
        }
        if (M >= 60)
        {
            H += M / 60;
            M = M % 60;
        }
        if (H > 24)
        {
            D += H / 24;
            H = H % 24;
        }
        Console.WriteLine("D := " + D + " AND Time Now "    + H + ":" + M + ":" + S);
    }
}

