        Discount = int.Parse(Console.ReadLine());
        if (Salary <= 5200)
            Tax += 0;
        else if (Salary > 5200 && Salary <= 8900)
            Tax += (Salary - 5200) * 0.1;
        else if (Salary > 8900 && Salary <= 14200)
            Tax += (Salary - 8900) * 0.25;
        else if (Salary > 14200 && Salary <= 18900)
